async function syncFromSheets() {
  const saveLabel=el('saveState'); if(saveLabel)saveLabel.textContent='Conectando ao sistema…';
  try {
    const data=await hubEsc().chamar('escCarregar');
    ESC_FIN=!!data.financeiro;
    const asText=v=>v==null?'':String(v);
    const dateValue=v=>{if(!v)return'';const t=String(v);const m=t.match(/^(\d{4}-\d{2}-\d{2})/);if(m)return m[1];const d=new Date(v);return Number.isNaN(+d)?t:d.toISOString().slice(0,10)};
    if(Array.isArray(data.motoristas) && data.motoristas.length){
      catalog.drivers=data.motoristas.map(m=>({
        id:asText(m.ID), name:m['NOME COMPLETO']||m.NOME||'', cpf:m.CPF||'', rg:m.RG||'',
        role:m.FUNCAO||m['FUNÇÃO']||'MOTORISTA', type:m.TIPO||'', birthday:dateValue(m['DATA DE ANIVERSARIO']||m['DATA DE ANIVERSÁRIO']),
        whatsapp:m.WHATSAPP||'', plate:m['PLACA DO VEICULO']||m['PLACA DO VEÍCULO']||m.PLACA||'',
        licenseNumber:m['NUMERO DA CNH']||m['NÚMERO DA CNH']||'', licenseCategory:m['CATEGORIA DA CNH']||'',
        licenseExpiry:dateValue(m['VALIDADE DA CNH']), apisulRelease:m['LIBERACAO APISUL']||m['LIBERAÇÃO APISUL']||'',
        apisulExpiry:dateValue(m['VALIDADE APISUL']), fixedHelperId:m['AJUDANTE FIXO']||'',
        active:String(m.ATIVO).toLowerCase()!=='false'?'true':'false'
      })).filter(x=>x.name);
      catalog.vehicles=[...new Set(catalog.drivers.map(d=>d.plate).filter(Boolean))];
    }
    if(Array.isArray(data.ajudantes) && data.ajudantes.length){
      catalog.helpers=data.ajudantes.map(a=>({
        id:asText(a.ID), name:a['NOME COMPLETO']||a.NOME||'', cpf:a.CPF||'', rg:a.RG||'',
        role:a.FUNCAO||a['FUNÇÃO']||'AJUDANTE', type:a.TIPO||'', birthday:dateValue(a['DATA DE ANIVERSARIO']||a['DATA DE ANIVERSÁRIO']),
        whatsapp:a.WHATSAPP||'', apisulRelease:a['LIBERACAO APISUL']||a['LIBERAÇÃO APISUL']||'',
        apisulExpiry:dateValue(a['VALIDADE APISUL']), fixedDriverId:a['MOTORISTA FIXO']||'',
        active:String(a.ATIVO).toLowerCase()!=='false'?'true':'false'
      })).filter(x=>x.name);
    }
    normalizePersonLinks();
    if(Array.isArray(data.escala)){
      records=data.escala.map(r=>({
        id:asText(r.ID_REGISTRO||r.ID)||crypto.randomUUID(), idEscala:r.ID_ESCALA||'',
        statusEscala:r.STATUS_ESCALA||'PRÉVIA', versao:Number(r.VERSAO)||1,
        criadaEm:r.CRIADA_EM||'', criadaPor:r.CRIADA_POR||'', confirmadaEm:r.CONFIRMADA_EM||'',
        confirmadaPor:r.CONFIRMADA_POR||'', justificativaAjuste:r.JUSTIFICATIVA_AJUSTE||'',
        box:r.BOX||'', driver:r.MOTORISTA||'', vehicle:r['VEICULO/PLACA']||r['VEÍCULO/PLACA']||r.VEICULO||'',
        helper1:r['AJUDANTE 1']||r.AJUDANTE1||'', helper2:r['AJUDANTE 2']||'', load:r.CARGA||'', status:r.STATUS||'',
        std:r.STD||r['STD ONLINE']||'', collect:r.COLETA||'', route:r.ROTA||'', qty:r['QTD P']||'', cub:r.CUB||'',
        route2:r['ROTA2 / REGIAO']||r.ROTA2||r.REGIAO||'', routeCode:r['COD REGIAO']||r['COD. REGIAO']||'',
        date:dateValue(r.DATA_OPERACAO||r.DATA), transpo:r.TRANSPO||r.TRANSPORTADORA||'',
        stopped:r['MOTORISTAS PARADOS']||'', reason:r.MOTIVO||'', period:r.PERIODO||r['PERÍODO']||'', imageStatus:r.STATUS_IMAGEM||'', departureAt:r.SAIDA_CD||'', departureBy:r.RESPONSAVEL_SAIDA_CD||'', releaseStatus:r.COLETA_LIBERADA||'', releaseAt:r.LIBERACAO_EM||'', releaseBy:r.LIBERADO_POR||'', departureSheet:r.URL_FOLHA_CARGA||'', cdDeparture:r.SAIDA_CD?{at:r.SAIDA_CD,by:r.RESPONSAVEL_SAIDA_CD||''}:null, collectionRelease:r.LIBERACAO_EM?{at:r.LIBERACAO_EM,by:r.LIBERADO_POR||''}:null
      })).filter(r=>r.load||r.driver||r.box);
    }
    save(); renderCatalog(); render(); renderCatalogViews();
    if(saveLabel)saveLabel.textContent='Conectado ao sistema';
    notify(`Base atualizada: ${catalog.drivers.length} motoristas e ${catalog.helpers.length} ajudantes`);
    return true;
  } catch(err) {
    console.warn('Falha na sincronização com sistema:',err);
    if(saveLabel)saveLabel.textContent='sistema indisponível';
    notify(`Não consegui ler a base do sistema: ${err.message||'verifique a publicação do servidor'}`);
    return false;
  }
}
function normalizePersonLinks(){
  const resolve=(value,list)=>{const key=normCell(value);const match=(list||[]).find(x=>String(personId(x))===String(value)||normCell(personValue(x,'name'))===key);return match?personId(match):value||''};
  (catalog.drivers||[]).forEach(d=>{d.fixedHelperId=resolve(d.fixedHelperId,catalog.helpers)});
  (catalog.helpers||[]).forEach(h=>{h.fixedDriverId=resolve(h.fixedDriverId,catalog.drivers)});
}
async function postToSheets(p){
  const mapa={salvar_escala:['escSalvar',{registros:p.registros}],confirmar_definitiva:['escConfirmar',{dataOperacao:p.dataOperacao,justificativa:p.justificativa}],
    verificar_escala_limpeza:['escVerificarLimpeza',{registros:p.registros}],limpar_escala:['escLimpar',{registros:p.registros,confirmar:p.confirmar}],
    salvar_motoristas:['escSalvarCadastro',{tipo:'motoristas',registros:p.registros}],salvar_ajudantes:['escSalvarCadastro',{tipo:'ajudantes',registros:p.registros}],excluir_registro:['escExcluir',{id:p.id}]};
  const m=mapa[p.action]; if(!m)throw Error('Ação desconhecida.');
  return await hubEsc().chamar(m[0],m[1]);
}
