async function enviarFoto(dataUrl,ref){const r=await hubEsc().chamar('escFolhaEnviar',{imagemBase64:dataUrl,data:ref.date||localISO(),carga:ref.load||''});return r.url}
async function saveCatalogOnline(kind, list){
  const action=kind==='drivers'?'salvar_motoristas':'salvar_ajudantes';
  return await postToSheets({action,registros:list});
}
function prepareScaleRows(items){
  const now=new Date().toISOString();
  return items.map(r=>{
    if(!r.id)r.id=crypto.randomUUID();
    const date=r.date||'';
    return {
      id:r.id,idEscala:r.idEscala||`ESC-${date||'SEM-DATA'}-V${r.versao||1}`,
      dateOperation:date,statusEscala:r.statusEscala||'PRÉVIA',version:Number(r.versao)||1,
      createdAt:r.criadaEm||now,createdBy:r.criadaPor||'Usuário da escala',
      confirmedAt:r.confirmadaEm||'',confirmedBy:r.confirmadaPor||'',revisionReason:r.justificativaAjuste||'',
      box:r.box||'',driver:r.driver||'',vehicle:r.vehicle||'',helper1:r.helper1||'',helper2:r.helper2||'',
      load:r.load||'',status:r.status||'',std:r.std||'',collect:r.collect||'',route:r.route||'',qty:r.qty||'',cub:r.cub||'',
      route2:r.route2||'',routeCode:r.routeCode||'',date:r.date||date,transpo:r.transpo||'',stopped:r.stopped||'',
      reason:r.reason||'',period:r.period||'',
      imageStatus:r.departureSheet?'IMAGEM ANEXADA':(r.imageStatus||'SEM IMAGEM'),departureUrl:/^https:/.test(r.departureSheet||'')?r.departureSheet:'',
      departureAt:r.cdDeparture?.at||r.departureAt||'',departureBy:r.cdDeparture?.by||r.departureBy||'',
      releaseStatus:r.collectionRelease?'COLETA LIBERADA':(r.releaseStatus||''),
      releaseAt:r.collectionRelease?.at||r.releaseAt||'',releaseBy:r.collectionRelease?.by||r.releaseBy||''
    };
  });
}
async function saveScaleOnline(items=records){
  const saveLabel=el('saveState'); if(saveLabel)saveLabel.textContent='Gravando escala no sistema…';
  try{
    const result=await postToSheets({action:'salvar_escala',registros:prepareScaleRows(items)});
    if(saveLabel)saveLabel.textContent=`Escala gravada no sistema (${result.updated||0} alteradas, ${result.inserted||0} novas)`;
    return result;
  }catch(err){
    if(saveLabel)saveLabel.textContent='Falha ao gravar no sistema';
    notify(`Não gravou no sistema: ${err.message||'verifique a implantação e o acesso'}`);
    return null;
  }
}
function getOperationDate(){
  const chosen=el('dateFilter')?.value||'';
  const dates=[...new Set(records.map(r=>String(r.date||'').slice(0,10)).filter(Boolean))];
  if(chosen)return chosen;
  return dates.length===1?dates[0]:'';
}
function rowsForOperation(date){return records.filter(r=>String(r.date||'').slice(0,10)===date)}
async function savePreviewToSheets(){
  const date=getOperationDate(); if(!date)return notify('Selecione a data da operação no filtro; para salvar uma PRÉVIA é necessário identificar o dia.');
  const rows=rowsForOperation(date); if(!rows.length)return notify(`Não há registros para ${date}.`);
  rows.forEach(r=>{r.statusEscala='PRÉVIA';r.dateOperation=date;r.idEscala=r.idEscala||`ESC-${date}-V${r.versao||1}`});
  save(); const result=await saveScaleOnline(rows);
  if(result)notify(`PRÉVIA de ${date} gravada no sistema (${rows.length} cargas).`);
}
async function confirmDefinitiveInSheets(){
  const date=getOperationDate(); if(!date)return notify('Selecione a data da operação no filtro antes de confirmar.');
  const rows=rowsForOperation(date); if(!rows.length)return notify(`Não há registros para ${date}.`);
  const already=rows.some(r=>String(r.statusEscala||'').toUpperCase()==='DEFINITIVA');
  const justification=already?prompt('A escala já está DEFINITIVA. Informe a justificativa para criar uma nova versão imutável:',''):'';
  if(already && justification===null)return;
  if(already && !justification.trim())return notify('A justificativa é obrigatória para uma nova versão.');
  rows.forEach(r=>{r.statusEscala='PRÉVIA';r.dateOperation=date;r.justificativaAjuste=justification||''});
  save(); const saved=await saveScaleOnline(rows); if(!saved)return;
  try{
    const result=await postToSheets({action:'confirmar_definitiva',dataOperacao:date,justificativa:justification||''});
    rows.forEach(r=>{r.statusEscala='DEFINITIVA';r.versao=result.version||r.versao||1;r.idEscala=result.idEscala||r.idEscala});
    save(); render();
    notify(result.already?result.message:`ESCALA DEFINITIVA gravada no histórico: ${result.total||rows.length} cargas.`);
  }catch(err){notify(`Não foi possível confirmar a definitiva: ${err.message||'erro de gravação'}`)}
}

async function clearScaleProtected(){
  if(!records.length){
    notify('A tela não tem cargas para comparar. Atualize a escala pelo sistema antes de limpar.');
    return;
  }
  const button=el('clearScaleBtn');
  if(button)button.disabled=true;
  const snapshot=records.map(r=>({...r}));
  try{
    if(el('saveState'))el('saveState').textContent='Conferindo se a escala está salva no sistema…';
    const check=await postToSheets({action:'verificar_escala_limpeza',registros:prepareScaleRows(snapshot)});
    if(!check.ready){
      const detail=check.message||'Os registros da tela não conferem com a escala ativa.';
      notify(`Limpeza bloqueada: ${detail}`);
      if(el('saveState'))el('saveState').textContent='Conferência falhou; nenhuma linha foi apagada';
      return;
    }
    const total=Number(check.total||snapshot.length);
    const previas=Number(check.previas||0), definitivas=Number(check.definitivas||0);
    const warning=`CONFERÊNCIA CONCLUÍDA: ${total} carga(s) da tela conferem com a escala ativa do sistema.\n\nANTES DE CONTINUAR, confira se você salvou a PRÉVIA ou confirmou a DEFINITIVA. A limpeza apagará somente os dados ativos da escala ativa e a cópia local da escala. O histórico definitivo, cadastros e coletas NÃO serão apagados.\n\nNa base foram identificadas ${previas} PRÉVIA(S) e ${definitivas} DEFINITIVA(S).\n\nDeseja limpar agora?`;
    if(!confirm(warning)){
      if(el('saveState'))el('saveState').textContent='Limpeza cancelada; escala mantida';
      return;
    }
    if(el('saveState'))el('saveState').textContent='Limpando somente a escala ativa…';
    // O servidor confere novamente, sob bloqueio, antes de apagar para evitar alteração concorrente.
    const result=await postToSheets({action:'limpar_escala',confirmar:true,registros:prepareScaleRows(snapshot)});
    records=[];
    save();
    render();
    closeForm();
    if(el('saveState'))el('saveState').textContent='Aba ESCALA limpa no sistema';
    notify(`Escala limpa: ${result.cleared||0} linha(s) removida(s) somente da escala ativa. Histórico preservado.`);
  }catch(err){
    if(el('saveState'))el('saveState').textContent='Falha na conferência/limpeza; escala mantida';
    notify(`A escala não foi limpa: ${err.message||'falha na conferência'}`);
  }finally{if(button)button.disabled=false}
}

