   <div class="scale-summary-meta"><div><span class="scale-field-label">MOTORISTA E AJUDANTE(S)</span><div class="scale-team-inline"><strong>${esc(r.driver||'MOTORISTA NÃO ALOCADO')}</strong>${helperNames.length?`<span class="scale-team-sep" aria-hidden="true">·</span><span class="scale-team-helper"><span class="scale-team-label">AJUDANTE${helperNames.length>1?'S':''}:</span> ${helperNames.map(esc).join(' · ')}</span>`:`<span class="scale-team-helper scale-team-none">SEM AJUDANTE ALOCADO</span>`}</div></div><div><span class="scale-field-label">CÓD. REGIÃO + REGIÃO</span><strong>${esc(routeLabel(r))}</strong></div></div>
