let sharePngBlob=null,shareImageUrl=null;
async function refreshSharePreview(){const rows=shareRows();if(!rows.length){notify('Não há registros visíveis para compartilhar');return false}try{const svgBlob=new Blob([buildShareSvg(rows)],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(svgBlob),img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas'),scale=2;canvas.width=img.naturalWidth*scale;canvas.height=img.naturalHeight*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);sharePngBlob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!sharePngBlob)throw Error('Não foi possível gerar a imagem.');if(shareImageUrl)URL.revokeObjectURL(shareImageUrl);shareImageUrl=URL.createObjectURL(sharePngBlob);el('shareImagePreview').src=shareImageUrl;return true}catch(e){notify(e.message||'Falha ao gerar prévia');return false}}
function activeDriversNotAllocated(){const active=(catalog.drivers||[]).filter(d=>personValue(d,'active')!=='false'&&catalogName(d).trim());const allocated=new Set(records.map(r=>normCell(r.driver)));const others=['shareFolga','shareManutencao','shareDisponiveis','shareFalta'].flatMap(id=>(el(id)?.value||'').split(/[,;]+|\n/).map(normCell).filter(Boolean));return active.filter(d=>!allocated.has(normCell(catalogName(d)))&&!others.includes(normCell(catalogName(d))))}
function refreshDriverAllocations(){const box=el('driverAllocations');if(!box)return;const active=(catalog.drivers||[]).filter(d=>personValue(d,'active')!=='false'&&catalogName(d).trim());const allocated=new Set(records.map(r=>normCell(r.driver)));box.innerHTML=`<strong>Motoristas ativos da base — confira antes de compartilhar</strong><div class="sub">Motoristas podem ser repetidos na escala. Quem já estiver na escala permanece visível em cinza, com “Já incluído!”. Os que faltarem precisam ser colocados em uma opção de Outros ao compartilhar.</div><div class="driver-alloc-list">${active.map(d=>{const done=allocated.has(normCell(catalogName(d)));return `<span class="driver-chip ${done?'allocated':'pending'}">${esc(catalogName(d))} ${done?'✓ Já incluído!':'• Aguardando alocação em Outros'}</span>`}).join('')||'<span class="sub">Nenhum motorista ativo cadastrado.</span>'}</div></section>`;el('shareScaleBtn').classList.toggle('needs-review',activeDriversNotAllocated().length>0)}
function refreshShareDriverReview(){const box=el('shareDriverReview');if(!box)return;const missing=activeDriversNotAllocated();box.classList.toggle('hidden',missing.length===0);box.innerHTML=missing.length?`<strong>Faltam motoristas ativos em “Outros”</strong><span>Antes de compartilhar, inclua cada nome em Folga, Manutenção, Disponíveis ou Falta:</span><div class="driver-alloc-list">${missing.map(d=>`<span class="driver-chip pending">${esc(catalogName(d))}</span>`).join('')}</div>`:'';el('sendShareBtn').disabled=missing.length>0;el('sendShareBtn').title=missing.length?'Alocar todos os motoristas ativos em Outros antes de compartilhar':''}
