function downloadShareImage(){if(!sharePngBlob){notify('Atualize a prévia antes de baixar');return}const a=document.createElement('a');a.href=shareImageUrl;a.download='escala-transmarina-whatsapp.png';document.body.appendChild(a);a.click();a.remove();notify('Imagem da escala baixada')}
