function importCSV(file){const reader=new FileReader();reader.onload=()=>{try{const lines=parseCSV(String(reader.result||'').replace(/^﻿/,''));if(lines.length<2)throw Error('O CSV não possui linhas de dados.');const h=lines[0].map(normalizeHeader);const aliases={BOX:['BOX'],MOTORISTA:['MOTORISTA'],AJUDANTE1:['AJUDANTE1'],AJUDANTE2:['AJUDANTE2'],VEICULOPLACA:['VEICULOPLACA','VEICULO','PLACA'],CARGA:['CARGA'],STATUS:['STATUS'],STD:['STD'],COLETA:['COLETA'],ROTA:['ROTA'],QTDP:['QTDP','QUANTIDADE'],CUB:['CUB','CUBAGEM'],ROTA2:['ROTA2','DESCRICAODAREGIAO','REGIAO'],CODREGIAO:['CODREGIAO','CODIGOREGIAO'],DATA:['DATA'],TRANSPO:['TRANSPO','TRANSPORTADOR'],MOTORISTASPARADOS:['MOTORISTASPARADOS'],MOTIVO:['MOTIVO','MOTOTIVO'],PERIODO:['PERIODO']};const idx={};for(let j=0;j<h.length;j++)for(const [field,opts] of Object.entries(aliases))if(opts.includes(h[j]))idx[field]=j;const keyToField={BOX:'box',MOTORISTA:'driver',AJUDANTE1:'helper1',AJUDANTE2:'helper2',VEICULOPLACA:'vehicle',CARGA:'load',STATUS:'status',STD:'std',COLETA:'collect',ROTA:'route',QTDP:'qty',CUB:'cub',ROTA2:'route2',CODREGIAO:'routeCode',DATA:'date',TRANSPO:'transpo',MOTORISTASPARADOS:'stopped',MOTIVO:'reason',PERIODO:'period'};const imported=lines.slice(1).map(line=>{const r={id:crypto.randomUUID()};for(const [key,f] of Object.entries(keyToField)){if(idx[key]!=null){let v=(line[idx[key]]||'').trim();if(f==='date')v=normalizeDate(v);r[f]=v}}return r}).filter(r=>Object.values(r).some(v=>v&&v!==r.id));if(!imported.length)throw Error('Não encontrei registros reconhecíveis no CSV.');records=records.concat(imported);save();render();notify(`${imported.length} registros importados`)}catch(e){notify(e.message||'Não foi possível ler o CSV')}el('scaleImportInput').value=''};reader.readAsText(file,'utf-8')}
