async function readZipEntries(buffer){if(!('DecompressionStream'in window))throw Error('Este navegador não oferece suporte à leitura local deste Excel. Tente abrir o HTML em uma versão atualizada do Chrome.');const dv=new DataView(buffer);let end=-1;for(let p=Math.max(0,dv.byteLength-65558);p<=dv.byteLength-22;p++)if(dv.getUint32(p,true)===0x06054b50)end=p;if(end<0)throw Error('Não consegui reconhecer este arquivo como uma planilha Excel válida.');const count=dv.getUint16(end+10,true);let pos=dv.getUint32(end+16,true),out={};for(let i=0;i<count;i++){if(dv.getUint32(pos,true)!==0x02014b50)break;const method=dv.getUint16(pos+10,true),compressed=dv.getUint32(pos+20,true),nameLen=dv.getUint16(pos+28,true),extraLen=dv.getUint16(pos+30,true),commentLen=dv.getUint16(pos+32,true),local=dv.getUint32(pos+42,true),name=new TextDecoder().decode(new Uint8Array(buffer,pos+46,nameLen));const localName=dv.getUint16(local+26,true),localExtra=dv.getUint16(local+28,true),start=local+30+localName+localExtra,raw=new Uint8Array(buffer,start,compressed);if(method===0)out[name]=raw;else if(method===8){const ds=new DecompressionStream('deflate-raw');const stream=new Blob([raw]).stream().pipeThrough(ds);out[name]=new Uint8Array(await new Response(stream).arrayBuffer())}pos+=46+nameLen+extraLen+commentLen}return out}
function xlsxSheetRows(bytes,shared){const doc=xmlDoc(bytes);if(doc.querySelector('parsererror'))throw Error('A aba “2° PASSO” está com formato XML inválido.');const rows=[];for(const row of doc.getElementsByTagNameNS('*','row')){const vals=[];for(const c of row.getElementsByTagNameNS('*','c')){const ref=c.getAttribute('r')||'',letters=(ref.match(/[A-Z]+/)||['A'])[0];let ci=0;for(const ch of letters)ci=ci*26+ch.charCodeAt(0)-64;ci--;const t=c.getAttribute('t'),v=c.getElementsByTagNameNS('*','v')[0]?.textContent??'';let value=t==='s'?shared[Number(v)]??'':t==='inlineStr'?c.getElementsByTagNameNS('*','t')[0]?.textContent??'':t==='b'?(v==='1'?'TRUE':'FALSE'):v;vals[ci]=value}rows.push(vals)}return rows}
