async function getSecondPass(book){const wb=xmlDoc(book['xl/workbook.xml']),rels=xmlDoc(book['xl/_rels/workbook.xml.rels']);const sheet=[...wb.getElementsByTagNameNS('*','sheet')].find(s=>s.getAttribute('name')==='2° PASSO');if(!sheet)throw Error('Não encontrei a aba “2° PASSO” nesse Excel.');const rid=sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')||sheet.getAttribute('r:id');const rel=[...rels.getElementsByTagNameNS('*','Relationship')].find(r=>r.getAttribute('Id')===rid);if(!rel)throw Error('Não consegui localizar a aba “2° PASSO” dentro do Excel.');let target=rel.getAttribute('Target').replace(/^\//,'');if(!target.startsWith('xl/'))target='xl/'+target;const parts=[];for(const part of target.split('/')){if(part==='..')parts.pop();else if(part!=='.')parts.push(part)}target=parts.join('/');const shared=book['xl/sharedStrings.xml']?[...xmlDoc(book['xl/sharedStrings.xml']).getElementsByTagNameNS('*','si')].map(si=>[...si.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')):[];if(!book[target])throw Error('Não foi possível ler os dados da aba “2° PASSO”.');return xlsxSheetRows(book[target],shared)}
function normCell(v){return String(v??'').trim().normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().replace(/\s+/g,'')}
async function importAuto(file){try{const entries=await readZipEntries(await file.arrayBuffer());const rows=await getSecondPass(entries);const norm=rows.map(r=>r.map(normCell));const loadAliases=['CODIGO','CODIGOCARGA','CARGA','FCARGA','NUMEROCARGA','NUMCARGA'];const carrierAliases=['TRANSPORTADORA','TRANSPORTADOR','TRANSPO'];const headerIndex=norm.findIndex(r=>r.some(x=>carrierAliases.includes(x))&&r.some(x=>loadAliases.includes(x)));let mode='';if(headerIndex>=0){const h=norm[headerIndex],find=aliases=>h.findIndex(x=>aliases.includes(x));const cols={load:find(loadAliases),status:find(['SITUACAO','STATUS']),std:find(['DEST','DESTINO']),collect:find(['NF','NOTAFISCAL']),route:find(['ENTREGA','ROTA']),qty:find(['PARADAS','QTDP','QUANTIDADE']),cub:find(['UTILIZ','UTILIZACAO','CUB','CUBAGEM','CUBAGEMM3']),route2:find(['DESCRICAODAREGIAO','REGIAO']),routeCode:find(['CODREGIAO','CODIGOREGIAO']),date:find(['DATA','DATADAESCALA']),transpo:find(carrierAliases),box:find(['BOX','NUMEROBOX','BOXES','IDBOX'])};const fullSignals=['PARADAS','QTDP','QUANTIDADE','ENTREGA','ROTA','DEST','DESTINO','NF','NOTAFISCAL','UTILIZ','CUB','CUBAGEM','DESCRICAODAREGIAO','REGIAO','CODREGIAO','CODIGOREGIAO','DATA','DATADAESCALA','SITUACAO','STATUS'].some(x=>h.includes(x));if(cols.load>=0&&cols.transpo>=0&&fullSignals){mode='full';const incoming=new Map();for(let i=headerIndex+1;i<rows.length;i++){const row=rows[i]||[];if(normCell(row[cols.transpo])!=='BRAULIOCESAR')continue;const load=String(row[cols.load]??'').trim();if(!load)continue;const item={load};for(const f of ['status','std','collect','route','qty','cub','route2','routeCode','date']){const j=cols[f];if(j>=0){let value=String(row[j]??'').trim();if(f==='date')value=normalizeDate(value);item[f]=value}}if(cols.box>=0){const box=String(row[cols.box]??'').trim();if(box)item.box=box}incoming.set(normCell(load),item)}if(!incoming.size)throw Error('Não encontrei cargas do BRAULIO CESAR na planilha. Nenhum registro foi alterado.');const hasBox=cols.box>=0;const verb=hasBox?'com BOX':'sem BOX';if(!confirm(`Identifiquei uma planilha de fechamento ${verb}, com ${incoming.size} cargas. Vou atualizar os dados da escala; quando não houver BOX, preservarei os BOX e a equipe já cadastrados para cada carga. Continuar?`))return;const byLoad=new Map();for(const r of records){const key=normCell(r.load);if(key&&!byLoad.has(key))byLoad.set(key,r)}const replacement=[];let preserved=0,boxesUpdated=0;for(const [key,data] of incoming){const old=byLoad.get(key)||{};const target={id:old.id||crypto.randomUUID(),box:data.box||old.box||'',driver:old.driver||'',vehicle:old.vehicle||'',helper1:old.helper1||'',helper2:old.helper2||'',stopped:old.stopped||'',reason:old.reason||'',period:old.period||'',...data};if(old.id)preserved++;if(data.box)boxesUpdated++;replacement.push(target)}records=replacement;save();render();notify(`${replacement.length} cargas importadas automaticamente (${verb}); ${boxesUpdated} BOX identificados e ${preserved} registros existentes mesclados`);return}}const boxHeader=headerIndex>=0&&norm[headerIndex].some(x=>['BOX','NUMEROBOX','BOXES','IDBOX'].includes(x));let keyCol=-1,carrierCol=-1,boxCol=-1,start=0,layout='';if(boxHeader){const h=norm[headerIndex],find=aliases=>h.findIndex(x=>aliases.includes(x));keyCol=find(loadAliases);carrierCol=find(carrierAliases);boxCol=find(['BOX','NUMEROBOX','BOXES','IDBOX']);start=headerIndex+1;layout='cabeçalhos identificados'}else{keyCol=1;carrierCol=11;boxCol=0;start=0;layout='colunas padrão da planilha com BOX (BOX A, CARGA B, transportadora L)'}if(keyCol<0||carrierCol<0||boxCol<0)throw Error('Não reconheci a planilha. Use o fechamento com ou sem os cabeçalhos de BOX e CARGA. Nenhum dado foi alterado.');const boxByLoad=new Map();for(let i=start;i<rows.length;i++){const row=rows[i]||[];if(normCell(row[carrierCol])!=='BRAULIOCESAR')continue;const load=normCell(row[keyCol]),box=String(row[boxCol]??'').trim();if(load&&box)boxByLoad.set(load,box)}if(!boxByLoad.size)throw Error(`Não encontrei cargas e BOX (${layout}). Nenhum dado foi alterado.`);const currentByLoad=new Map(records.map(r=>[normCell(r.load),r]));let changed=0;for(const [load,box] of boxByLoad){const r=currentByLoad.get(load);if(r){r.box=box;changed++}}if(!changed)throw Error(`Identifiquei ${boxByLoad.size} relações de carga e BOX, mas não achei cargas correspondentes na escala atual. Importe primeiro o fechamento completo (com ou sem BOX). Nenhum dado foi alterado.`);records.sort((a,b)=>String(a.box||'').localeCompare(String(b.box||''),'pt-BR',{numeric:true,sensitivity:'base'}));save();render();notify(`${changed} BOX mesclados automaticamente às cargas existentes`)}catch(e){notify(e.message||'Não foi possível identificar o formato da planilha')}el('scaleImportInput').value=''}
