function saveCollection(e){e.preventDefault();const load=el('collectionLoad').value.trim(),driver=el('collectionDriver').value.trim();if(!load){notify('Cadastre ou selecione uma carga na escala antes de lançar a coleta');return}const items=[...el('collectionItems').querySelectorAll('.collectionItem')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-cfield]')].map(input=>[input.dataset.cfield,input.value.trim()]))).filter(x=>x.nf||x.std||x.customer||x.cep||x.microzone||x.reason);if(!items.length){notify('Adicione pelo menos uma nota de coleta');return}const c={id:editingCollectionId||crypto.randomUUID(),load,driver,date:el('collectionDate').value,issueDate:el('collectionIssueDate').value,folio:el('collectionFolio').value.trim(),route:el('collectionRoute').value.trim(),branch:el('collectionBranch').value.trim(),volumes:el('collectionVolumes').value,carrier:el('collectionCarrier').value.trim(),box:el('collectionBox').value.trim(),items};if(editingCollectionId){const i=collections.findIndex(x=>x.id===editingCollectionId);if(i>=0)collections[i]=c;else collections.push(c)}else collections.push(c);save();render();closeCollection();notify(`Coleta da carga ${load} salva; Microzonas por nota fiscal`)}
