const SUPPLIED_MGM_VERSION=1;
let financeData={charges:{},rates:[]},financeLoad=null;
function loadFinance(){financeData={charges:{},rates:[]}}
function aplicarFinance(cargas,fin){
  financeData={charges:(cargas&&cargas.charges&&typeof cargas.charges==='object')?cargas.charges:{},rates:Array.isArray(fin&&fin.rates)?fin.rates:[]};
  if(ESC_FIN&&(!fin||fin.mgmTariffVersion!==SUPPLIED_MGM_VERSION)){for(const item of SUPPLIED_MGM_TARIFFS){const i=financeData.rates.findIndex(r=>mgmKey(r.mgm)===mgmKey(item.mgm));if(i<0)financeData.rates.push({...item});else financeData.rates[i]={...financeData.rates[i],...item}}agendarBlocos()}
}
function saveFinance(){agendarBlocos();el('saveState').textContent='Salvando…'}
function chargeKey(load){return normCell(load)}
function chargeData(load){const key=chargeKey(load);if(!financeData.charges[key])financeData.charges[key]={load,deliveries:[],draftDeliveries:null,photo:'',ocrText:''};if(!Array.isArray(financeData.charges[key].deliveries))financeData.charges[key].deliveries=[];return financeData.charges[key]}
function driverCatalogEntry(name){return (catalog.drivers||[]).find(d=>normCell(catalogName(d))===normCell(name))||null}
function normalizeWhatsApp(value){let n=String(value||'').replace(/\D/g,'');if(n.length===10||n.length===11)n='55'+n;return n.length>=12&&n.length<=13?n:''}
function departureControls(r){const hasDriver=!!String(r.driver||'').trim(),sheet=!!r.departureSheet,confirmed=!!r.cdDeparture,authorized=!!r.collectionRelease;let status,cls;if(!hasDriver){status='MOTORISTA NÃO ALOCADO · SAÍDA NÃO LIBERADA';cls='dep-red'}else if(authorized){status='COLETA LIBERADA · AVISO PREPARADO NO WHATSAPP';cls='dep-green'}else if(confirmed){status='SAÍDA DO CD CONFIRMADA · AGUARDANDO GESTOR';cls='dep-green'}else if(sheet){status='FOLHA DE CARGA ANEXADA · CONFIRME A SAÍDA';cls='dep-orange'}else{status='MOTORISTA ALOCADO · AGUARDANDO FOLHA DE CARGA';cls='dep-orange'}const photo=sheet?`<button type="button" class="btn" data-view-departure-sheet="${esc(r.id)}">Ver folha de carga</button>`:'';const upload=hasDriver?`<label class="btn departure-upload">${sheet?'Substituir folha':'Anexar folha de carga'}<input type="file" accept="image/*" data-upload-departure-sheet="${esc(r.id)}" aria-label="Anexar folha de carga para ${esc(r.driver)}"></label>`:`<button type="button" class="btn" disabled title="Alocar um motorista para habilitar">Anexar folha de carga</button>`;let action='';if(hasDriver&&sheet&&!confirmed)action=`<button type="button" class="btn primary" data-confirm-cd-departure="${esc(r.id)}">Confirmar saída do CD</button>`;if(hasDriver&&confirmed&&!authorized)action=`<button type="button" class="btn primary" data-release-collection="${esc(r.id)}">Liberar coleta e avisar motorista</button>`;const time=authorized&&r.collectionRelease?.at?`<div class="sub">Autorizada às ${esc(new Date(r.collectionRelease.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}. Confirme o envio no WhatsApp.</div>`:confirmed&&r.cdDeparture?.at?`<div class="sub">Saída registrada às ${esc(new Date(r.cdDeparture.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))}${r.cdDeparture.by?` · ${esc(r.cdDeparture.by)}`:''}</div>`:'';return `<div class="departure-control"><span class="departure-badge ${cls}">${esc(status)}</span><div class="departure-actions">${upload}${photo}${action}</div>${time}</div>`}
async function uploadDepartureSheet(id,file){if(!file)return;const r=records.find(x=>x.id===id);if(!r)return;if(!String(r.driver||'').trim()){notify('Alocar um motorista antes de anexar a folha de carga');return}if(!file.type||!file.type.startsWith('image/')){notify('Selecione uma imagem válida da folha de carga');return}try{const previous=r.departureSheet;notify('Enviando a folha de carga…');r.departureSheet=await enviarFoto(await compressDepartureSheet(file),r);r.cdDeparture=null;r.collectionRelease=null;if(!save()){r.departureSheet=previous;return}render();saveScaleOnline(prepareScaleRows([r]));notify('Folha de carga anexada. Confira a imagem e confirme a saída do CD quando o veículo efetivamente sair.')}catch(e){notify(e.message||'Não foi possível anexar a folha de carga')}}
function compressDepartureSheet(file){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1100/img.width),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.58));URL.revokeObjectURL(img.src)};img.onerror=()=>reject(Error('Não foi possível abrir a imagem da folha de carga.'));img.src=URL.createObjectURL(file)})}
function viewDepartureSheet(id){const r=records.find(x=>x.id===id);if(!r?.departureSheet){notify('Não há folha de carga anexada neste registro');return}const win=window.open('','_blank');if(!win){notify('Permita a abertura de nova aba para visualizar a folha de carga');return}win.document.write(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Folha de carga</title><body style="margin:0;background:#16191b;color:white;font:16px system-ui;text-align:center"><header style="padding:12px">Folha de carga · ${esc(r.driver)} · ${esc(r.vehicle||'Veículo não informado')} <button onclick="window.close()">Fechar</button></header><img src="${esc(r.departureSheet)}" alt="Folha de carga" style="max-width:100%;max-height:calc(100vh - 60px);object-fit:contain"></body></html>`);win.document.close()}
function confirmCDDeparture(id){const r=records.find(x=>x.id===id);if(!r)return;if(!String(r.driver||'').trim())return notify('Alocar um motorista antes de confirmar a saída');if(!r.departureSheet)return notify('Anexe e confira a folha de carga antes de confirmar a saída');const by=prompt('Confirme que o veículo efetivamente saiu do Centro de Distribuição. Informe o responsável pela confirmação:','Gestor da escala');if(by===null)return;r.cdDeparture={at:new Date().toISOString(),by:by.trim()||'Responsável não informado'};r.collectionRelease=null;save();render();saveScaleOnline(prepareScaleRows([r]));notify('Saída do CD registrada. Aguardando liberação da coleta pelo gestor.')}
function releaseCollection(id){const r=records.find(x=>x.id===id);if(!r)return;if(!r.cdDeparture)return notify('Confirme a saída efetiva do CD antes de liberar a coleta');const driver=driverCatalogEntry(r.driver),phone=normalizeWhatsApp(personValue(driver,'whatsapp'));if(!phone)return notify('Cadastre um WhatsApp válido com DDD no cadastro deste motorista');const region=routeLabel(r);const message=`Olá, ${r.driver}! Sua coleta foi liberada. Hoje você atenderá a região ${region==='—'?'a confirmar':region} e já pode iniciar a coleta pelo aplicativo ASAP. Por favor, faça o login ainda dentro do Centro de Distribuição (CD), antes de iniciar a primeira entrega, e não se esqueça de compartilhar sua localização no grupo. Boa viagem e bom trabalho!`;const url=`https://wa.me/${phone}?text=${encodeURIComponent(message)}`;const tab=window.open(url,'_blank');if(!tab){notify('O navegador bloqueou o WhatsApp. Permita pop-ups e tente novamente.');return}r.collectionRelease={at:new Date().toISOString(),by:'Gestor da escala'};save();render();saveScaleOnline(prepareScaleRows([r]));notify('Coleta liberada. Revise a mensagem e confirme o envio no WhatsApp.')}

function currentDeliveries(data){return Array.isArray(data.draftDeliveries)?data.draftDeliveries:data.deliveries}
function financeLoads(){const seen=new Set();return records.filter(r=>r.load&&String(r.load).trim()).filter(r=>{const k=chargeKey(r.load);if(seen.has(k))return false;seen.add(k);return true})}
function deliveryKey(v){return normCell(v).replace(/[^A-Z0-9]/g,'')}
function mgmKey(v){return deliveryKey(v).replace(/^(?:MGM|MGX)/,'').replace(/^0+(?=\d)/,'')}
function stopTotal(deliveries){const groups=new Map();for(const d of deliveries){const k=[d.customer,d.address,d.number].map(deliveryKey).join('|');if(!k.replaceAll('|',''))continue;groups.set(k,(groups.get(k)||0)+1)}let n=0;for(const count of groups.values())n+=Math.ceil(count/3);return n}
function rateEntry(mgm,stops){if(stops>40)return null;const r=financeData.rates.find(x=>mgmKey(x.mgm)===mgmKey(mgm));if(!r)return null;const raw=stops<=24?r.upto24:r.over24;if(raw===''||raw==null||!Number.isFinite(Number(raw)))return null;return Number(raw)}
function rateFor(mgm,stops){return rateEntry(mgm,stops)??0}
function freightTotal(items,stops){if(items.some(x=>rateEntry(deliveryZone(x),stops)===null))return null;return items.reduce((sum,x)=>sum+rateFor(deliveryZone(x),stops),0)}
function money(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v)||0)}
function findMicrozoneByCep(cep){const digits=String(cep||'').replace(/\D/g,'');return digits.length===8?CEP_MICROZONES[digits]||'':''}
