function renderRegionRouteMap(){const q=el('regionRouteSearch').value.trim().toLocaleLowerCase('pt-BR');const priority=PRIORITY_FREIGHT_ROUTES.filter(x=>!q||[x.code,x.name].join(' ').toLocaleLowerCase('pt-BR').includes(q));const filtered=REGION_ROUTE_MGM_BASE.filter(x=>!q||[x.regionCode,x.regionName,x.route,x.mgm].join(' ').toLocaleLowerCase('pt-BR').includes(q));const groups=new Map();for(const x of filtered){const key=`${x.regionCode}|${x.regionName}|${x.route}`;if(!groups.has(key))groups.set(key,{meta:x,items:[]});groups.get(key).items.push(x)}const ordered=[...groups.values()].sort((a,b)=>(Number(a.meta.regionCode)-Number(b.meta.regionCode))||a.meta.regionName.localeCompare(b.meta.regionName,'pt-BR')||a.meta.route.localeCompare(b.meta.route,'pt-BR'));const rateMap=new Map((financeData?.rates||[]).map(r=>[String(r.mgm||'').trim().toLocaleUpperCase('pt-BR'),r]));const priorityRows=priority.length?`<tr class="microzone-group-row priority-group-row"><td colspan="4">BRAULIO CESAR · TRANSMARINA · TRANSPORTES MARINA <span class="microzone-route-label">${priority.length} ROTAS</span></td></tr>`+priority.map(x=>`<tr class="priority-route-row"><td><strong>${esc(x.code)} · ${esc(x.name)}</strong></td><td class="route-cep-count">—</td><td class="priority-rate-value">${money(x.upto24)}</td><td class="priority-rate-value">${money(x.over25)}</td></tr>`).join(''):'';const mapRows=ordered.map(g=>{const m=g.meta;return `<tr class="microzone-group-row"><td colspan="4">REGIÃO ${esc(m.regionCode)} · ${esc(m.regionName)} <span class="microzone-route-label">ROTA ${esc(m.route)}</span> <span class="microzone-route-label">${g.items.length} MGM(s)</span></td></tr>`+g.items.map(x=>{const rate=rateMap.get(String(x.mgm||'').trim().toLocaleUpperCase('pt-BR'));return `<tr><td><strong>${esc(x.mgm)}</strong></td><td class="route-cep-count">${Number(x.cepCount).toLocaleString('pt-BR')}</td><td class="priority-rate-value">${rate?money(rate.upto24):'—'}</td><td class="priority-rate-value">${rate?money(rate.over25??rate.over24):'—'}</td></tr>`}).join('')}).join('');el('regionRouteRows').innerHTML=priorityRows+mapRows||'<tr><td colspan="4" class="finance-empty">Nenhum resultado encontrado para esta busca.</td></tr>';const totalRegions=new Set(REGION_ROUTE_MGM_BASE.map(x=>x.regionCode)).size;const totalRoutes=new Set(REGION_ROUTE_MGM_BASE.map(x=>x.route)).size;el('regionRouteCount').textContent=q?`${priority.length} rota(s) prioritária(s) · ${filtered.length.toLocaleString('pt-BR')} vínculo(s)`: `${priority.length} rotas prioritárias · ${totalRoutes} rotas · ${totalRegions} regiões`;el('regionRouteMeta').textContent=q?`${priority.length+filtered.length} resultado(s)`:'2.441 CEPs na base'}function showFinanceSubtab(name){const dashboard=name==='dashboard',loads=name==='loads',zones=name==='microzones',routes=name==='regionRoute';[['financeDashboardTab',dashboard],['financeLoadsTab',loads],['microzonesTab',zones],['regionRouteTab',routes]].forEach(([id,on])=>{el(id).classList.toggle('active',on);el(id).setAttribute('aria-selected',String(on))});el('financeDashboardContent').classList.toggle('hidden',!dashboard);el('financeLoadsContent').classList.toggle('hidden',!loads);el('microzonesContent').classList.toggle('hidden',!zones);el('regionRouteContent').classList.toggle('hidden',!routes);if(routes)renderRegionRouteMap();if(dashboard)renderDashboard()}function deliveryZone(d){return findMicrozoneByCep(d.cep)||d.mgm||''}
function updateCepStatus(delivery,row){const status=row.querySelector('[data-cep-status]');if(!status)return;const matched=findMicrozoneByCep(delivery.cep),select=row.querySelector('select[data-field="mgm"]');if(matched){delivery.mgm=matched;if(select)select.value=matched;status.textContent=`✓ ${matched} identificada automaticamente pelo CEP`;status.className='microzone-status ok'}else if(String(delivery.cep||'').replace(/\D/g,'').length===8){status.textContent=delivery.mgm?`⚠ CEP fora da base; confira a microzona manual: ${delivery.mgm}`:'⚠ CEP fora da base regional — selecione a microzona manualmente';status.className='microzone-status warn'}else{status.textContent='';status.className='microzone-status'}}
