const OPERATION_DAILY_COSTS={driver:271.57,helper1:215.79,helper2:236.87,supervisor:29.54};
function numericValue(value){if(typeof value==='number')return Number.isFinite(value)?value:0;let s=String(value??'').trim().replace(/R\$/gi,'').replace(/\s/g,'');if(!s)return 0;if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');const n=Number(s);return Number.isFinite(n)?n:0}
function normalizeRouteText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim()}
function scaleStops(r,items){const q=numericValue(r?.qty);return q>0?q:items?stopTotal(items):0}
function routeCodeDigits(r){const raw=String(r?.routeCode||'').trim();const m=raw.match(/\d{1,5}/);if(m)return String(Number(m[0]));const other=`${r?.route2||''} ${r?.route||''}`.match(/(?:COD(?:IGO)?\.?\s*)?(\d{1,5})\b/i);return other?String(Number(other[1])):''}
function aggregateRateForRecord(r){const code=routeCodeDigits(r);if(code){const found=AGGREGATE_REGION_RATES.find(x=>x.code&&String(Number(x.code))===code);if(found)return found}const text=normalizeRouteText(`${r?.route2||''} ${r?.route||''} ${routeLabel(r)}`);return AGGREGATE_REGION_RATES.find(x=>x.alias&&text.includes(normalizeRouteText(x.alias)))||null}
function revenueRateForRecord(r,stops){const code=routeCodeDigits(r);let found=code?PRIORITY_FREIGHT_ROUTES.find(x=>String(Number(x.code))===code):null;if(!found){const text=normalizeRouteText(`${r?.route2||''} ${r?.route||''} ${routeLabel(r)}`);found=PRIORITY_FREIGHT_ROUTES.find(x=>text.includes(normalizeRouteText(x.name))||normalizeRouteText(x.name).includes(text)&&text.length>4)}if(!found)return null;const unit=numericValue(stops<=24?found.upto24:found.over25);return unit>0?unit:null}
function estimatedRouteRevenue(r,items){const stops=scaleStops(r,items),unit=revenueRateForRecord(r,stops);return unit===null||stops<=0?null:{stops,unit,total:stops*unit,band:stops<=24?'0–24':'25+'}}
function classifiedDriverType(name){const d=driverCatalogEntry(name);const t=normalizeRouteText(personValue(d,'type'));if(t==='CLT'||t.includes(' CLT'))return 'CLT';if(t.includes('AGREGADO'))return 'AGREGADO';return ''}
function dateLoadCount(date){const matching=records.filter(x=>String(x.date||'')===String(date||''));return Math.max(1,matching.length)}
function managerDailyShare(r){return OPERATION_DAILY_COSTS.supervisor/dateLoadCount(r?.date)}
function scenarioCosts(r,items){const stops=scaleStops(r,items),helpers=[r?.helper1,r?.helper2].map(x=>String(x||'').trim()).filter(Boolean),manager=managerDailyShare(r);let clt=OPERATION_DAILY_COSTS.driver+manager;if(helpers.length>0)clt+=OPERATION_DAILY_COSTS.helper1;if(helpers.length>1)clt+=OPERATION_DAILY_COSTS.helper2;if(helpers.length===1&&stops>=20)clt+=40;const rate=aggregateRateForRecord(r);const aggregate=rate&&stops>0?rate.heavy*stops+rate.unload+manager:null;return{stops,helpers,manager,clt,aggregate,rate,actualType:classifiedDriverType(r?.driver),actual:classifiedDriverType(r?.driver)==='CLT'?clt:classifiedDriverType(r?.driver)==='AGREGADO'?aggregate:null}}
function costBadge(type){return type==='CLT'?'<span class="type-badge clt">CLT</span>':type==='AGREGADO'?'<span class="type-badge aggregate">AGREGADO</span>':'<span class="type-badge">VÍNCULO PENDENTE</span>'}
function operationalCostSummary(r){const c=scenarioCosts(r),recommended=c.aggregate===null?'<span class="dash-status warn">SEM TARIFA AGREGADA</span>':c.clt<=c.aggregate?'<span class="dash-status ok">CLT MENOR</span>':'<span class="dash-status ok">AGREGADO MENOR</span>';const actual=c.actual===null?'<span class="scale-field-sub">Custo efetivo estimado: pendente — confira vínculo/tarifa no cadastro/base.</span>':`<span class="scale-field-sub">Modelo cadastrado: ${esc(c.actualType)} · custo estimado ${money(c.actual)} · CLT ${money(c.clt)} · agregado ${c.aggregate===null?'sem tarifa':money(c.aggregate)} · ${recommended}</span>`;return `<div><span class="scale-field-label">INDICATIVO OPERACIONAL AUTOMÁTICO</span><strong>${costBadge(c.actualType)} ${c.stops} parada(s) · ${recommended}</strong>${actual}</div>`}
function dashboardRows(){const date=el('dashDate')?.value||'';return records.filter(r=>!date||String(r.date||'')===date)}
function renderDashboard(){const body=el('dashComparisonRows');if(!body)return;const rows=dashboardRows(),computed=rows.map(r=>{const finance=financeData?.charges?.[chargeKey(r.load)]||null,items=finance?(Array.isArray(finance.draftDeliveries)?finance.draftDeliveries:finance.deliveries):null;return{r,c:scenarioCosts(r,items),revenue:estimatedRouteRevenue(r,items)}});const sum=key=>computed.reduce((n,x)=>n+(typeof x[key]==='number'?x[key]:0),0),knownRevenue=computed.filter(x=>x.revenue),knownActual=computed.filter(x=>x.c.actual!==null),totalRevenue=knownRevenue.reduce((n,x)=>n+x.revenue.total,0),totalClt=sum('clt'),totalAggregate=computed.reduce((n,x)=>n+(x.c.aggregate??0),0),actualTotal=knownActual.reduce((n,x)=>n+x.c.actual,0);el('dashRevenue').textContent=knownRevenue.length?money(totalRevenue):'Sem tarifa de faturamento';el('dashActualCost').textContent=knownActual.length?money(actualTotal):'Vínculo pendente';el('dashFleetCost').textContent=rows.length?money(totalClt):money(0);el('dashAggregateCost').textContent=computed.every(x=>x.c.aggregate!==null)?money(totalAggregate):'Tarifa regional pendente';const bands={'0–24':0,'25+':0};computed.forEach(x=>{if(x.c.stops>0)bands[x.c.stops<=24?'0–24':'25+']++});el('dashCommonBand').textContent=bands['0–24']+bands['25+']?`${bands['0–24']>=bands['25+']?'0–24':'25+'} paradas · ${Math.max(bands['0–24'],bands['25+'])} carga(s)`:'Sem paradas informadas';const regions=new Map();for(const x of knownRevenue){const label=routeLabel(x.r);const cur=regions.get(label)||{loads:0,stops:0,total:0};cur.loads++;cur.stops+=x.revenue.stops;cur.total+=x.revenue.total;regions.set(label,cur)}const regionRows=[...regions.entries()].sort((a,b)=>b[1].total-a[1].total);el('dashHighRegion').textContent=regionRows.length?`${regionRows[0][0]} · ${money(regionRows[0][1].total)}`:'—';el('dashLowRegion').textContent=regionRows.length?`${regionRows[regionRows.length-1][0]} · ${money(regionRows[regionRows.length-1][1].total)}`:'—';el('dashRegionRows').innerHTML=regionRows.length?regionRows.map(([name,v])=>`<tr><td>${esc(name)}</td><td>${v.loads}</td><td>${v.stops}</td><td>${money(v.total)}</td></tr>`).join(''):'<tr><td colspan="4" class="finance-empty">Sem tarifa regional compatível ou sem paradas informadas.</td></tr>';const choice=totalClt<=totalAggregate?'CLT':'AGREGADO';el('dashCheaperScenario').textContent=rows.length&&computed.every(x=>x.c.aggregate!==null)?`${choice} · ${money(Math.min(totalClt,totalAggregate))}`:'Comparação incompleta';el('dashComparisonRows').innerHTML=computed.length?computed.map(({r,c,revenue})=>{const winner=c.aggregate===null?'Tarifa agregada pendente':c.clt<=c.aggregate?'CLT · menor estimativa':'AGREGADO · menor estimativa';const actual=c.actualType?`${c.actualType}${c.actual===null?' · custo pendente':''}`:'Vínculo pendente — atualizar cadastro';return `<tr><td>${esc(formatDate(r.date))} · ${esc(r.load||'—')}</td><td>${esc(routeLabel(r))}</td><td>${c.stops||'—'}</td><td>${esc(actual)}</td><td>${money(c.clt)}</td><td>${c.aggregate===null?'Tarifa pendente':money(c.aggregate)}</td><td>${esc(winner)}</td></tr>`}).join(''):'<tr><td colspan="7" class="finance-empty">Nenhum registro na escala para exibir.</td></tr>';const missingType=computed.filter(x=>!x.c.actualType).length,missingAgg=computed.filter(x=>x.c.aggregate===null).length,missingRevenue=computed.filter(x=>!x.revenue).length;const n=el('dashDataNote');if(n){n.textContent=`Estimativa somente operacional. Foram selecionados ${rows.length} registro(s); ${missingType} sem vínculo CLT/agregado no cadastro; ${missingAgg} sem tarifa pesada/descarga regional; ${missingRevenue} sem tarifa de faturamento por região. Custos incluídos: motorista CLT R$ 271,57/dia, ajudante R$ 215,79/dia, segundo ajudante R$ 236,87/dia, encarregado R$ 29,54/dia rateado por carga da mesma data, dobra de R$ 40 somente para CLT com um ajudante e 20+ paradas; agregado = tarifa pesada regional × paradas + descarga. Não inclui combustível, manutenção ou outros valores que não estejam na base.`}}
function renderRates(){el('mgmRates').innerHTML=financeData.rates.length?financeData.rates.map((r,i)=>`<tr class="rate-row"><td><strong>${esc(r.mgm)}</strong></td><td><input class="rate-input" type="number" min="0" step="0.01" value="${esc(r.upto24??'')}" data-rate="${i}" data-band="upto24" aria-label="Tarifa ${esc(r.mgm)} até 24 paradas"></td><td><input class="rate-input" type="number" min="0" step="0.01" value="${esc(r.over24??'')}" data-rate="${i}" data-band="over24" aria-label="Tarifa ${esc(r.mgm)} de 25 a 40 paradas"></td><td><button class="iconbtn" data-rate-remove="${i}" type="button">Remover</button></td></tr>`).join(''):'<tr><td colspan="4" class="finance-empty">Cadastre os MGMs e suas tarifas para calcular o frete.</td></tr>'}
function renderFinance(){renderRates();const loads=financeLoads();el('financeLoadCount').textContent=`${loads.length} ${loads.length===1?'carga':'cargas'}`;el('financeLoadList').innerHTML=loads.length?loads.map(r=>{const d=chargeData(r.load),items=currentDeliveries(d),stops=stopTotal(items),total=freightTotal(items,stops);return `<button type="button" class="finance-load-card ${financeLoad===r.load?'selected':''}" data-finance-load="${esc(r.load)}"><span class="finance-load-meta"><strong>Carga ${esc(r.load)}</strong><span class="sub">${esc(r.driver||'Motorista não definido')} · ${esc(formatDate(r.date))}</span><span class="sub">${d.deliveries.length} entrega(s) · ${stops} parada(s) · ${total===null?'Frete pendente':money(total)}</span></span><span class="finance-badge ${summaryImageStatus(r.load).className==='summary-confirmed'?'ready':d.photo?'review':'missing'}">${summaryImageStatus(r.load).text}</span></button>`}).join(''):'<div class="finance-empty">Nenhuma carga cadastrada na escala.</div>';const report=el('financeReport');report.classList.toggle('hidden',!financeLoad);if(!financeLoad)return;const row=loads.find(r=>chargeKey(r.load)===chargeKey(financeLoad));if(!row){financeLoad=null;report.classList.add('hidden');return}const data=chargeData(row.load),items=currentDeliveries(data),stops=stopTotal(items),total=freightTotal(items,stops);el('financeReviewActions').classList.toggle('hidden',!Array.isArray(data.draftDeliveries));if(Array.isArray(data.draftDeliveries)){const issues=items.reduce((n,d)=>n+deliveryIssues(d).length,0),hint=el('financeReviewHint');hint.classList.toggle('ok',issues===0&&items.length>0);hint.textContent=items.length?issues?`${items.length} entrega(s) extraída(s). ${issues} campo(s) precisam de conferência; os campos destacados devem ser corrigidos.`:'Os campos obrigatórios parecem preenchidos. Confira os dados antes de confirmar.':'Não encontrei linhas confiáveis. O cabeçalho foi ignorado; confira o texto reconhecido ou cadastre manualmente.'}el('financeTitle').textContent=`Relatório financeiro — Carga ${row.load}`;el('financeSubtitle').textContent=`${row.driver||'Motorista não definido'} · ${formatDate(row.date)}`;el('financeDeliveryCount').textContent=items.length;el('financeStopCount').textContent=stops;el('financeFreightTotal').textContent=total===null?'Tarifas pendentes':money(total);el('financeDeliveries').innerHTML=items.length?items.map((d,i)=>{const zone=findMicrozoneByCep(d.cep),digits=String(d.cep||'').replace(/\D/g,'');return `<tr class="${deliveryIssues(d).length?'review-warning':''}">${[['nf','NF'],['customer','Cliente'],['cep','CEP'],['address','Endereço'],['number','Nº'],['neighborhood','Bairro']].map(([k,label])=>`<td><input class="${fieldNeedsCorrection(d,k)?'needs-correction':''}" data-delivery="${i}" data-field="${k}" value="${esc(d[k]||'')}" aria-label="${label}" placeholder="${label}" title="${fieldNeedsCorrection(d,k)?'Confira ou preencha este campo':''}"></td>`).join('')}<td><select class="${!zone&&!d.mgm?'needs-correction':''}" data-delivery="${i}" data-field="mgm" aria-label="MGM"><option value="">Selecione</option>${financeData.rates.map(r=>`<option value="${esc(r.mgm)}" ${mgmKey(deliveryZone(d))===mgmKey(r.mgm)?'selected':''}>${esc(r.mgm)}</option>`).join('')}</select><small data-cep-status class="microzone-status ${zone?'ok':digits.length===8?'warn':''}">${zone?'✓ '+esc(zone)+' identificada pelo CEP':digits.length===8?(d.mgm?'⚠ CEP fora da base; confira MGM manual':'⚠ CEP fora da base — corrija MGM manualmente'):'⚠ Confira o CEP'}</small></td><td>${rateEntry(deliveryZone(d),stops)===null?'Tarifa pendente':money(rateFor(deliveryZone(d),stops))}</td><td><button type="button" class="iconbtn" data-delivery-remove="${i}">Excluir</button></td></tr>`}).join(''):'<tr><td colspan="9" class="finance-empty">Ainda não há entregas nesta carga. Anexe a foto para consultar o texto reconhecido e adicione/revise as entregas.</td></tr>' ;el('financePhotoArea').innerHTML=data.photo?`<div class="finance-photo-card"><strong>Resumo anexado à carga</strong><button class="iconbtn" type="button" data-photo-remove>Remover foto</button><img src="${data.photo}" alt="Resumo de entregas anexado"><label class="sub" for="ocrTextReview">Texto reconhecido pela leitura OCR — revise e use para completar as entregas abaixo</label><textarea id="ocrTextReview">${esc(data.ocrText||'')}</textarea><button class="btn" type="button" id="saveOcrText">Salvar texto revisado</button></div>`:''}
function showMainView(view){const catalogMode=view==='catalog',financeMode=view==='finance';el('scaleView').classList.toggle('hidden',catalogMode||financeMode);el('catalogView').classList.toggle('hidden',!catalogMode);el('financeView').classList.toggle('hidden',!financeMode);el('scaleTab').classList.toggle('active',!catalogMode&&!financeMode);el('catalogTab').classList.toggle('active',catalogMode);el('financeTab').classList.toggle('active',financeMode);el('pageTitle').textContent=catalogMode?'Cadastros':financeMode?'Financeiro':'Planejamento de rotas';el('pageDescription').textContent=catalogMode?'Gerencie os cadastros usados na escala.':financeMode?'Acompanhe o Dashboard, faturamento e tarifas por carga.':'Edite a escala, organize equipes e acompanhe as cargas.';if(catalogMode)renderCatalogViews();if(financeMode){showFinanceSubtab('dashboard');renderFinance()}}
function fieldNeedsCorrection(d,key){if(key==='number')return false;if(key==='cep')return String(d.cep||'').replace(/\D/g,'').length!==8;return !String(d[key]||'').trim()}
function deliveryIssues(d){const a=[];for(const [k,n] of [['nf','NF'],['customer','cliente'],['cep','CEP'],['address','endereço'],['neighborhood','bairro']])if(fieldNeedsCorrection(d,k))a.push(n);if(!findMicrozoneByCep(d.cep)&&!String(d.mgm||'').trim())a.push('microzona');return a}
