function confirmFinanceReview(){if(!financeLoad)return;const data=chargeData(financeLoad),items=currentDeliveries(data),pending=items.reduce((n,d)=>n+deliveryIssues(d).length,0);if(pending){notify(`${pending} campo(s) precisam de correção antes de confirmar. Confira os destaques laranja.`);el('financeReviewHint').scrollIntoView({behavior:'smooth',block:'center'});return}data.deliveries=items.map(x=>({...x}));data.draftDeliveries=null;saveFinance();renderFinance();notify('Entregas confirmadas e salvas na carga')}
