function compressPhoto(file){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1500/img.width),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.68));URL.revokeObjectURL(img.src)};img.onerror=()=>reject(Error('Não foi possível abrir esta foto.'));img.src=URL.createObjectURL(file)})}
function prepareOCRImage(file){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{try{const scale=Math.max(2,Math.min(3,2200/img.width)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,c.width,c.height);const d=x.getImageData(0,0,c.width,c.height);for(let i=0;i<d.data.length;i+=4){const g=.299*d.data[i]+.587*d.data[i+1]+.114*d.data[i+2],v=Math.max(0,Math.min(255,(g-145)*1.45+145));d.data[i]=d.data[i+1]=d.data[i+2]=v}x.putImageData(d,0,0);resolve(c.toDataURL('image/png'));URL.revokeObjectURL(img.src)}catch(e){reject(e)}};img.onerror=()=>reject(Error('Não foi possível preparar a imagem para leitura.'));img.src=URL.createObjectURL(file)})}
function parseSummaryOCR(text){const rows=[];for(const raw of String(text||'').split(/\r?\n/)){const line=raw.replace(/[\u00a0]/g,' ').trim();if(!line)continue;const nf=line.match(/^\s*(\d{6,9})\b/);if(!nf)continue;const rest=line.slice(nf[0].length),cm=/(\d{5}[- .]?\d{3})/.exec(rest);if(!cm)continue;const customer=rest.slice(0,cm.index).replace(/[|;:–—-]+/g,' ').replace(/\s+/g,' ').trim(),cep=cm[1].replace(/\D/g,'');if(!customer||cep.length!==8)continue;let tail=rest.slice(cm.index+cm[0].length).trim().replace(/^\s*[|;:–—-]+\s*/,'');let parts=tail.includes('|')?tail.split(/\s*\|\s*/):tail.split(/\t+|\s{2,}/);parts=parts.map(x=>x.replace(/^[|;:–—-]+|[|;:–—-]+$/g,'').replace(/\s+/g,' ').trim()).filter(Boolean);let address=parts[0]||'',number='';if(parts.length>1&&/^(?:SN|S\s*\/?\s*N|N[ºO°.]?\s*\d+|\d+[A-Z]?(?:\/\d+)?)$/i.test(parts[1]))number=parts.splice(1,1)[0];const neighborhood=parts.length>=2?parts[parts.length-2]:'';const row={id:crypto.randomUUID(),nf:nf[1],customer,cep,address,number,neighborhood,mgm:findMicrozoneByCep(cep)};if(!rows.some(x=>x.nf===row.nf&&x.cep===row.cep))rows.push(row)}return rows}
async function attachSummary(file){if(!file)return;if(!financeLoad){notify('Selecione primeiro uma carga para anexar o resumo.');return}if(!file.type||!file.type.startsWith('image/')){notify('Escolha uma imagem válida para continuar.');return}const load=financeLoad;try{notify('Abrindo a conferência do resumo…');const data=chargeData(load);data.photo=await enviarFoto(await compressPhoto(file),{date:localISO(),load});data.draftDeliveries=data.deliveries.map(x=>({...x}));data.ocrText='Processando a imagem…';saveFinance();renderFinance();el('financeReviewActions').scrollIntoView({behavior:'smooth',block:'center'});try{const OCR=await loadOCR(),image=await prepareOCRImage(file),result=await OCR.recognize(image,'por',{}, {tessedit_pageseg_mode:'6',preserve_interword_spaces:'1'});data.ocrText=result.data.text||'';const parsed=parseSummaryOCR(data.ocrText);if(parsed.length)data.draftDeliveries=parsed.map(x=>({...data.deliveries.find(d=>d.nf===x.nf),...x}));else if(!data.deliveries.length)data.draftDeliveries=[]}catch(e){data.ocrText='A leitura OCR não foi concluída. Confira a foto e cadastre as entregas manualmente.';if(!data.deliveries.length)data.draftDeliveries=[]}saveFinance();renderFinance();el('financeReviewActions').scrollIntoView({behavior:'smooth',block:'center'});notify(data.draftDeliveries.length?`${data.draftDeliveries.length} entrega(s) para revisar`:'Resumo anexado. Não encontrei linhas confiáveis; revise o texto e cadastre as entregas.')}catch(e){notify(e.message||'Não foi possível anexar a foto')}el('summaryPhotoInput').value=''}
