el('scanSummaryBtn').addEventListener('click',openSummaryScanner);el('closeSummaryScanner').addEventListener('click',closeSummaryScanner);el('cancelSummaryScanner').addEventListener('click',closeSummaryScanner);el('summaryScannerOverlay').addEventListener('click',e=>{if(e.target===el('summaryScannerOverlay'))closeSummaryScanner()});el('scannerFallbackBtn').addEventListener('click',()=>el('scannerFallbackInput').click());el('scannerFallbackInput').addEventListener('change',e=>{const file=e.target.files&&e.target.files[0];if(file)attachSummary(file);e.target.value=''});el('captureSummaryBtn').addEventListener('click',async()=>{const video=el('summaryCameraVideo');if(!video.videoWidth||!video.videoHeight){notify('A câmera ainda está iniciando. Aguarde um instante e tente novamente.');return}try{const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Falha ao capturar a imagem.')),'image/jpeg',.92));const file=new File([blob],`resumo-${Date.now()}.jpg`,{type:'image/jpeg'});closeSummaryScanner();await attachSummary(file)}catch(err){notify(err.message||'Não foi possível capturar a foto')}});el('addDeliveryBtn').onclick=addDelivery;
