// Consulta do histórico definitivo no servidor. Não altera registros.
let historyRows = [];
let historyWasLoaded = false;
function historyNorm(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function historyPick(row, aliases){const map={};Object.keys(row||{}).forEach(k=>map[historyNorm(k)]=row[k]);for(const a of aliases){const k=historyNorm(a);if(Object.prototype.hasOwnProperty.call(map,k)&&map[k]!==''&&map[k]!=null)return map[k]}return ''}
const HISTORY_FIELDS={date:['DATA_OPERACAO','DATA DA OPERACAO','DATA'],version:['VERSAO','VERSÃO','VERSION'],load:['ID_CARGA','CARGA','NUMERO_CARGA','NÚMERO DA CARGA','Nº CARGA','LOAD'],box:['BOX','Nº BOX','NUMERO BOX','BOX_ID','ID_BOX','CAIXA'],collectOnline:['COLETA ONLINE','COLETA_ONLINE','NF_COLETA','NOTA DA COLETA','NOTA FISCAL DA COLETA','NUMERO NF COLETA','NÚMERO DA NF DA COLETA','REFERENCIA COLETA'],driver:['MOTORISTA','NOME_MOTORISTA','DRIVER'],helper:['AJUDANTE','AJUDANTE1','AJUDANTE 1','AJUDANTES'],helper2:['AJUDANTE2','AJUDANTE 2'],plate:['VEICULO/PLACA','VEÍCULO/PLACA','VEICULO','VEÍCULO','PLACA','VEHICLE'],region:['REGIAO','REGIÃO','ROTA2 / REGIAO','ROTA2','REGION'],route:['ROTA','ROUTE'],stops:['PARADAS','QTD P','QTD_P','QUANTIDADE PARADAS','STOP_COUNT'],nf:['NFS','NF','NOTAS FISCAIS','NUMERO NF','NF CARGA','NOTA FISCAL CARGA'],collect:['COLETA','STD','STD ONLINE','COLETA_ID','COLETA_LIBERADA'],tariff:['TARIFA','FRETE','VALOR FRETE','VALOR TARIFA'],status:['STATUS_ESCALA','STATUS'],reason:['JUSTIFICATIVA_AJUSTE','JUSTIFICATIVA','MOTIVO DO AJUSTE'],confirmedBy:['CONFIRMADA_POR','CONFIRMADO_POR'],confirmedAt:['CONFIRMADA_EM','CONFIRMADO_EM'],image:['STATUS_IMAGEM','STATUS DA IMAGEM'],departure:['SAIDA_CD','SAÍDA CD','SAIDA DO CD'],release:['COLETA_LIBERADA','STATUS_LIBERACAO','STATUS LIBERAÇÃO']};
function historyDate(row){let v=historyPick(row,HISTORY_FIELDS.date);if(!v)return '';let s=String(v);let m=s.match(/^(\d{4}-\d{2}-\d{2})/);if(m)return m[1];m=s.match(/^(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})$/);return m?`${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`:''}
function historyDisplayDate(s){return s?new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(`${s}T12:00:00Z`)):'Data não informada'}
function historyVersion(row){const v=historyPick(row,HISTORY_FIELDS.version);if(v!=='')return String(v);const id=String(historyPick(row,['ID_ESCALA'])||'');const m=id.match(/-V(\d+)$/i);return m?m[1]:'1'}
function historyEsc(value){return esc(value==null||value===''?'—':value)}
function historyParamsObj(){return Object.fromEntries(historySearchParams())}
function historySearchParams(){const p=new URLSearchParams({action:'historico',ts:String(Date.now())});const values={from:el('historyFrom').value,to:el('historyTo').value,region:el('historyRegion').value.trim(),route:el('historyRoute').value.trim(),version:el('historyVersion').value.trim()};Object.entries(values).forEach(([k,v])=>{if(v)p.set(k,v)});return p}
function historyVisibleEntries(){const q=historyNorm(el('historyQuery').value.trim());return historyRows.map((row,index)=>({row,index})).filter(({row})=>{if(!q)return true;const values=[historyPick(row,HISTORY_FIELDS.load),historyPick(row,HISTORY_FIELDS.box),historyPick(row,HISTORY_FIELDS.collectOnline),historyPick(row,HISTORY_FIELDS.driver),historyPick(row,HISTORY_FIELDS.nf),historyPick(row,HISTORY_FIELDS.collect),historyPick(row,HISTORY_FIELDS.plate)];return values.some(value=>historyNorm(value).includes(q))})}
async function loadHistory(){const status=el('historyStatus'),results=el('historyResults'),button=el('historySearchBtn');status.textContent='Consultando as abas de histórico no sistema…';results.innerHTML='<div class="empty"><strong>Carregando histórico</strong>Aguarde a resposta do servidor.</div>';button.disabled=true;el('historyRefreshBtn').disabled=true;try{const data=await hubEsc().chamar('escHistorico',historyParamsObj());if(!Array.isArray(data.historico))throw Error('A resposta não contém a lista do histórico. Atualize o servidor com a nova ação de consulta.');historyRows=data.historico;historyWasLoaded=true;renderHistory();status.textContent=`Consulta concluída · ${historyVisibleEntries().length.toLocaleString('pt-BR')} carga(s) correspondem à busca.`;el('historyExportBtn').disabled=!historyRows.length;return true}catch(err){historyRows=[];renderHistory();status.textContent=`Falha na consulta: ${err.message||'verifique a implantação do servidor'}`;notify(`Histórico não carregado: ${err.message||'verifique o servidor'}`,'error');return false}finally{button.disabled=false;el('historyRefreshBtn').disabled=false}}
function historyMoney(raw){if(raw===''||raw==null)return null;const n=typeof raw==='number'?raw:Number(String(raw).replace(/[^\d,.-]/g,'').replace(/\.(?=\d{3}(?:\D|$))/g,'').replace(',','.'));return Number.isFinite(n)?n:null}
function renderHistory(){const host=el('historyResults'),entries=historyVisibleEntries(),groups=new Map();entries.forEach(({row})=>{const date=historyDate(row)||'SEM-DATA',version=historyVersion(row);if(!groups.has(date))groups.set(date,new Set());groups.get(date).add(version)});const tariffValues=entries.map(({row})=>historyMoney(historyPick(row,HISTORY_FIELDS.tariff))).filter(v=>v!==null);el('historyLoadCount').textContent=entries.length.toLocaleString('pt-BR');el('historyVersionCount').textContent=[...groups.values()].reduce((n,v)=>n+v.size,0).toLocaleString('pt-BR');el('historyTariffTotal').textContent=tariffValues.length?money(tariffValues.reduce((a,b)=>a+b,0)):'—';if(!entries.length){host.innerHTML=`<div class="history-grid-empty"><strong>${historyWasLoaded?'Nenhum resultado encontrado':'Histórico ainda não carregado'}</strong><br>${historyWasLoaded?'Altere a busca ou os filtros para ver outros registros.':'Ao abrir esta aba, os registros existentes serão consultados.'}</div>`;return}host.innerHTML=`<table class="history-grid" aria-label="Histórico de cargas"><thead><tr><th>DATA / VERSÃO</th><th>CARGA</th><th>BOX</th><th>COLETA ONLINE</th><th>MOTORISTA</th><th>REGIÃO / ROTA</th><th>AÇÃO</th></tr></thead><tbody>${entries.map(({row,index})=>historyCard(row,index,groups.get(historyDate(row)||'SEM-DATA')?.size>1)).join('')}</tbody></table>`}
function historyCard(row,index,hasCompare){const load=historyPick(row,HISTORY_FIELDS.load)||historyPick(row,['ID_CARGA','CARGA']),date=historyDate(row),box=historyPick(row,HISTORY_FIELDS.box),online=historyPick(row,HISTORY_FIELDS.collectOnline),driver=historyPick(row,HISTORY_FIELDS.driver),region=[historyPick(row,HISTORY_FIELDS.region),historyPick(row,HISTORY_FIELDS.route)].filter(Boolean).join(' · '),version=historyVersion(row);const compare=hasCompare?`<button class="btn grid-compare" type="button" data-history-compare="${esc(date||'SEM-DATA')}">Comparar versões</button>`:'';return `<tr><td data-label="DATA / VERSÃO"><strong>${historyDisplayDate(date)}</strong><span class="grid-meta"><span class="history-badge">V${historyEsc(version)} · DEFINITIVA</span></span>${compare}</td><td data-label="CARGA" class="load-cell">${historyEsc(load)}</td><td data-label="BOX">${historyEsc(box)}</td><td data-label="COLETA ONLINE">${historyEsc(online)}</td><td data-label="MOTORISTA">${historyEsc(driver)}</td><td data-label="REGIÃO / ROTA">${historyEsc(region)}</td><td data-label="AÇÃO" class="grid-action"><button class="btn" type="button" data-history-detail="${index}">Ver detalhes</button></td></tr>`}
function openHistoryModal(title,html){el('historyModalTitle').textContent=title;el('historyModalBody').innerHTML=html;el('historyOverlay').classList.add('open')}
function closeHistoryModal(){el('historyOverlay').classList.remove('open')}
function showHistoryDetail(index){const row=historyRows[Number(index)];if(!row)return;const hidden=/CPF|RG|WHATSAPP|TELEFONE|TOKEN|SENHA|CHAVE|BASE64|IMAGEM.*DADOS/i;const entries=Object.entries(row).filter(([k,v])=>!k.startsWith('__')&&!hidden.test(k)&&v!==''&&v!=null);const summary=[['CARGA',historyPick(row,HISTORY_FIELDS.load)],['BOX',historyPick(row,HISTORY_FIELDS.box)],['COLETA ONLINE',historyPick(row,HISTORY_FIELDS.collectOnline)]];const reason=historyPick(row,HISTORY_FIELDS.reason);const html=`<p class="help">CARGA ${historyEsc(historyPick(row,HISTORY_FIELDS.load))} · ${historyDisplayDate(historyDate(row))} · ESCALA V${historyEsc(historyVersion(row))}</p><div class="history-detail-grid">${summary.map(([label,value])=>`<div class="history-detail-item"><small>${label}</small><div>${historyEsc(value)}</div></div>`).join('')}${entries.map(([k,v])=>`<div class="history-detail-item"><small>${historyEsc(k)}</small><div>${historyEsc(v)}</div></div>`).join('')}</div>${reason?`<div class="notice"><strong>Justificativa da nova versão:</strong> ${historyEsc(reason)}</div>`:''}`;openHistoryModal('Detalhes da carga',html)}
function compareHistoryVersions(date){const dayRows=historyRows.filter(r=>(historyDate(r)||'SEM-DATA')===date);const versions=[...new Set(dayRows.map(historyVersion))].sort((a,b)=>(Number(a)||0)-(Number(b)||0));if(versions.length<2)return;const oldV=versions[versions.length-2],newV=versions[versions.length-1],oldRows=dayRows.filter(r=>historyVersion(r)===oldV),newRows=dayRows.filter(r=>historyVersion(r)===newV);const loadKey=r=>historyNorm(historyPick(r,HISTORY_FIELDS.load));const oldMap=new Map(oldRows.map(r=>[loadKey(r),r]));const newMap=new Map(newRows.map(r=>[loadKey(r),r]));const changed=[];for(const [key,nr] of newMap){const or=oldMap.get(key);if(!or){changed.push(`<tr><td>Carga ${historyEsc(historyPick(nr,HISTORY_FIELDS.load))}</td><td colspan="3">Adicionada na V${historyEsc(newV)}</td></tr>`);continue}const checks=[['Motorista',HISTORY_FIELDS.driver],['Ajudante',HISTORY_FIELDS.helper],['Placa',HISTORY_FIELDS.plate],['Região',HISTORY_FIELDS.region],['Rota',HISTORY_FIELDS.route],['Paradas',HISTORY_FIELDS.stops],['NFs',HISTORY_FIELDS.nf],['Coleta',HISTORY_FIELDS.collect],['BOX',HISTORY_FIELDS.box],['COLETA ONLINE',HISTORY_FIELDS.collectOnline]];checks.forEach(([label,aliases])=>{const before=String(historyPick(or,aliases)||''),after=String(historyPick(nr,aliases)||'');if(historyNorm(before)!==historyNorm(after))changed.push(`<tr class="history-change"><td>Carga ${historyEsc(historyPick(nr,HISTORY_FIELDS.load))}</td><td>${label}</td><td>${historyEsc(before)}</td><td>${historyEsc(after)}</td></tr>`)})}for(const [key,or] of oldMap)if(!newMap.has(key))changed.push(`<tr><td>Carga ${historyEsc(historyPick(or,HISTORY_FIELDS.load))}</td><td colspan="3">Removida na V${historyEsc(newV)}</td></tr>`);const reason=historyPick(newRows[0]||{},HISTORY_FIELDS.reason);const html=`<p class="help">Comparação de ${historyDisplayDate(date)} · V${historyEsc(oldV)} para V${historyEsc(newV)}. A versão anterior continua preservada.</p>${reason?`<div class="notice"><strong>Justificativa da V${historyEsc(newV)}:</strong> ${historyEsc(reason)}</div>`:''}<div class="tablewrap"><table class="history-compare-table"><thead><tr><th>Carga</th><th>Campo</th><th>Antes · V${historyEsc(oldV)}</th><th>Depois · V${historyEsc(newV)}</th></tr></thead><tbody>${changed.join('')||'<tr><td colspan="4" class="history-empty">Não foi possível identificar diferenças nos campos operacionais retornados.</td></tr>'}</tbody></table></div>`;openHistoryModal('Comparar versões',html)}
function exportHistoryCsv(){const rows=historyVisibleEntries().map(({row})=>row);if(!rows.length)return notify('Não há resultados para exportar');const keys=[...new Set(rows.flatMap(r=>Object.keys(r).filter(k=>!k.startsWith('__'))))];const csv=[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`historico-cargas-${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function showHistoryTab(){showMainView('scale');el('scaleView').classList.add('hidden');el('catalogView').classList.add('hidden');el('financeView').classList.add('hidden');el('historyView').classList.remove('hidden');['scaleTab','catalogTab','financeTab'].forEach(id=>el(id).classList.remove('active'));el('historyTab').classList.add('active');el('pageTitle').textContent='Histórico de cargas';el('pageDescription').textContent='Consulte cargas definitivas, versões e registros operacionais.';if(!historyWasLoaded)loadHistory()}
const showMainViewBeforeHistory=showMainView;
showMainView=function(view){el('historyView').classList.add('hidden');el('historyTab').classList.remove('active');showMainViewBeforeHistory(view)};
el('historyTab').addEventListener('click',showHistoryTab);
el('historySearchBtn').addEventListener('click',loadHistory);el('historyQuery').addEventListener('input',()=>{renderHistory();if(historyWasLoaded)el('historyStatus').textContent=`Consulta concluída · ${historyVisibleEntries().length.toLocaleString('pt-BR')} carga(s) correspondem à busca.`});
el('historyRefreshBtn').addEventListener('click',loadHistory);
el('historyClearBtn').addEventListener('click',()=>{['historyQuery','historyFrom','historyTo','historyRegion','historyRoute','historyVersion'].forEach(id=>el(id).value='');loadHistory()});
el('historyExportBtn').addEventListener('click',exportHistoryCsv);
el('historyResults').addEventListener('click',e=>{const detail=e.target.closest('[data-history-detail]'),compare=e.target.closest('[data-history-compare]');if(detail)showHistoryDetail(detail.dataset.historyDetail);else if(compare)compareHistoryVersions(compare.dataset.historyCompare)});
['historyQuery','historyRegion','historyRoute','historyVersion'].forEach(id=>el(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();loadHistory()}}));
['historyFrom','historyTo'].forEach(id=>el(id).addEventListener('change',()=>{}));
el('historyModalClose').addEventListener('click',closeHistoryModal);el('historyModalDone').addEventListener('click',closeHistoryModal);el('historyOverlay').addEventListener('click',e=>{if(e.target===el('historyOverlay'))closeHistoryModal()});



// =====================================================================
// HUB TRANSMARINA: sessão, gravação em blocos e navegação por abas do Hub
// =====================================================================
let ESC_FIN=false;
function hubEsc(){const p=window.parent&&window.parent.HubEsc;if(!p)throw Error('Abra as Escalas pelo Hub Transmarina.');return p}
const BL={ver:{},ultimo:{},salvando:false,fila:false,tempo:null};
function montarBlocos(){const b={coletas:collections,cargas:{charges:financeData.charges},logradouros:streetEdits};if(ESC_FIN)b.financeiro={rates:financeData.rates,mgmTariffVersion:SUPPLIED_MGM_VERSION};return b}
function aplicarBlocos(d){
  if(Array.isArray(d.coletas))collections=d.coletas;
  streetEdits=Array.isArray(d.logradouros)?d.logradouros:[];
  aplicarFinance(d.cargas,d.financeiro);
}
function agendarBlocos(){BL.fila=true;clearTimeout(BL.tempo);BL.tempo=setTimeout(()=>{if(!BL.salvando)enviarBlocos()},700)}
async function enviarBlocos(){
  BL.salvando=true;
  try{
    while(BL.fila){
      BL.fila=false;
      const atual=montarBlocos(),partes={},bases={};
      Object.keys(atual).forEach(k=>{const t=JSON.stringify(atual[k]);if(t!==BL.ultimo[k]){partes[k]=atual[k];bases[k]=BL.ver[k]||0}});
      if(!Object.keys(partes).length)continue;
      const r=await hubEsc().chamar('escDadosSalvar',{partes,bases});
      BL.ver=r.versoes||BL.ver;Object.keys(partes).forEach(k=>{BL.ultimo[k]=JSON.stringify(partes[k])});
    }
    el('saveState').textContent='✔ Salvo';
  }catch(e){
    BL.fila=false;el('saveState').textContent='Não salvou';notify(e.message||'Não foi possível salvar.');
    await carregarBlocos();render();renderFinance();
  }
  BL.salvando=false;
}
async function carregarBlocos(){
  try{
    const r=await hubEsc().chamar('escDadosCarregar');
    aplicarBlocos(r.dados||{});BL.ver=r.versoes||{};
    const m=montarBlocos();BL.ultimo={};Object.keys(m).forEach(k=>{if((r.dados||{})[k]!=null)BL.ultimo[k]=JSON.stringify(m[k])});
  }catch(e){notify('Não consegui carregar coletas e resumos: '+(e.message||''))}
}
async function iniciarEscalas(){
  await syncFromSheets();           // traz a escala, os cadastros e diz se a pessoa tem o Financeiro
  await carregarBlocos();
  renderCatalog();render();renderCatalogViews();renderFinance();try{renderStreetCatalog()}catch(e){}
  el('financeTab').classList.toggle('hidden',!ESC_FIN);
  try{window.parent.postMessage({tipo:'esc-pronto',financeiro:ESC_FIN},location.origin)}catch(e){}
}
const _showMainViewHub=showMainView;
showMainView=function(v){if(v==='finance'&&!ESC_FIN){notify('Você não tem acesso ao Financeiro.');return}_showMainViewHub(v)};
window.addEventListener('message',e=>{
  if(e.origin!==location.origin||!e.data||e.data.tipo!=='esc-aba')return;
  const b={scale:'scaleTab',catalog:'catalogTab',finance:'financeTab',history:'historyTab'}[e.data.aba];if(b)el(b).click();
});
